```js
function throttle(fn, wait) {
  let last = 0;
  let timer = null;

  return function (...args) {
    const remaining = wait - (Date.now() - last);

    if (remaining <= 0) {
      clearTimeout(timer);
      timer = null;
      last = Date.now();
      fn.apply(this, args);
    } else if (!timer) {
      // Trailing call so the final scroll position isn't missed
      timer = setTimeout(() => {
        last = Date.now();
        timer = null;
        fn.apply(this, args);
      }, remaining);
    }
  };
}

const onScroll = throttle(() => {
  console.log('scrollY:', window.scrollY);
}, 200);

window.addEventListener('scroll', onScroll, { passive: true });
```

The handler fires immediately on the first scroll event, then at most once per 200 ms while scrolling continues, with one trailing call after scrolling stops so you always act on the final position.

`{ passive: true }` tells the browser the handler won't call `preventDefault()`, so scrolling isn't blocked waiting on it.

To remove it later, call `window.removeEventListener('scroll', onScroll)` with the same `onScroll` reference.
